                subtractive_aw_arb_rr <= (subtractive_aw_arb_gnt == 2'd3) ? 2'd0 : subtractive_aw_arb_gnt + 1'b1;
            end else if (subtractive_axi_awvalid) begin
                subtractive_aw_arb_lock   <= subtractive_aw_arb_gnt;
                subtractive_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 2'd0) && subtractive_aw_arb_req[0];
    wire dma_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 2'd1) && subtractive_aw_arb_req[1];
    wire atg_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 2'd2) && subtractive_aw_arb_req[2];
    wire cdma_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 2'd3) && subtractive_aw_arb_req[3];
    assign cpu_128b_aw_slot_subtractive_ready = cpu_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign dma_128b_aw_slot_subtractive_ready = dma_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign atg_128b_aw_slot_subtractive_ready = atg_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign cdma_128b_aw_slot_subtractive_ready = cdma_128b_aw_gnt_subtractive && subtractive_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign subtractive_axi_awid = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.id : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.id : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.id : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.id : '0);
    assign subtractive_axi_awaddr = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.addr : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.addr : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.addr : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.addr : '0);
    assign subtractive_axi_awlen = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.len : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.len : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.len : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.len : '0);
    assign subtractive_axi_awsize = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.size : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.size : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.size : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.size : '0);
    assign subtractive_axi_awburst = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.burst : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.burst : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.burst : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.burst : '0);
    assign subtractive_axi_awlock = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.lock : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.lock : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.lock : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.lock : '0);
    assign subtractive_axi_awcache = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.cache : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.cache : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.cache : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.cache : '0);
    assign subtractive_axi_awprot = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.prot : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.prot : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.prot : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.prot : '0);
    assign subtractive_axi_awqos = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.qos : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.qos : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.qos : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.qos : '0);
    assign subtractive_axi_awregion = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.region : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.region : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.region : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.region : '0);
    assign subtractive_axi_awuser = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.user : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_128b_aw_slot_subtractive.user : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.user : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.user : '0);
    assign subtractive_axi_awvalid = cpu_128b_aw_gnt_subtractive || dma_128b_aw_gnt_subtractive || atg_128b_aw_gnt_subtractive || cdma_128b_aw_gnt_subtractive;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [1:0] subtractive_wowner_mem [16];
    logic [4:0] subtractive_wowner_wptr, subtractive_wowner_rptr;
    logic subtractive_wowner_ahead;
    wire subtractive_wowner_valid = (subtractive_wowner_wptr != subtractive_wowner_rptr);
    wire subtractive_wowner_byp = !subtractive_wowner_valid && !subtractive_wowner_ahead && subtractive_axi_awvalid;
    wire subtractive_wowner_aw_hs = subtractive_axi_awvalid && subtractive_axi_awready;
    wire subtractive_wowner_w_end = subtractive_axi_wvalid && subtractive_axi_wready && subtractive_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_wowner_wptr  <= '0;
            subtractive_wowner_rptr  <= '0;
            subtractive_wowner_ahead <= 1'b0;
        end else begin
            if (subtractive_wowner_aw_hs && subtractive_wowner_ahead) begin
                subtractive_wowner_ahead <= 1'b0;   // its W already went
            end else if (subtractive_wowner_aw_hs && !(subtractive_wowner_byp && subtractive_wowner_w_end)) begin
                subtractive_wowner_mem[subtractive_wowner_wptr[3:0]] <= subtractive_aw_arb_gnt;
                subtractive_wowner_wptr <= subtractive_wowner_wptr + 1'b1;
            end else if (!subtractive_wowner_aw_hs && subtractive_wowner_byp && subtractive_wowner_w_end) begin
                subtractive_wowner_ahead <= 1'b1;
            end
            if (subtractive_wowner_valid && subtractive_wowner_w_end) begin
                subtractive_wowner_rptr <= subtractive_wowner_rptr + 1'b1;
            end
        end
    )
    wire [1:0] subtractive_wowner_head = subtractive_wowner_valid ? subtractive_wowner_mem[subtractive_wowner_rptr[3:0]]
                                       : subtractive_aw_arb_gnt;
    assign cpu_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 2'd0) && cpu_128b_w_to_subtractive;
    assign dma_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 2'd1) && dma_128b_w_to_subtractive;
    assign atg_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 2'd2) && atg_128b_w_to_subtractive;
    assign cdma_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 2'd3) && cdma_128b_w_to_subtractive;

    // W channel (owner-gated mux across writing masters)
    assign subtractive_axi_wdata = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.data : '0) |
        ((dma_128b_w_sel_subtractive && dma_128b_wvalid) ? dma_128b_w.data : '0) |
        ((atg_128b_w_sel_subtractive && atg_128b_wvalid) ? atg_128b_w.data : '0) |
        ((cdma_128b_w_sel_subtractive && cdma_128b_wvalid) ? cdma_128b_w.data : '0);
    assign subtractive_axi_wstrb = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.strb : '0) |
        ((dma_128b_w_sel_subtractive && dma_128b_wvalid) ? dma_128b_w.strb : '0) |
        ((atg_128b_w_sel_subtractive && atg_128b_wvalid) ? atg_128b_w.strb : '0) |
        ((cdma_128b_w_sel_subtractive && cdma_128b_wvalid) ? cdma_128b_w.strb : '0);
    assign subtractive_axi_wlast = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.last : '0) |
        ((dma_128b_w_sel_subtractive && dma_128b_wvalid) ? dma_128b_w.last : '0) |
        ((atg_128b_w_sel_subtractive && atg_128b_wvalid) ? atg_128b_w.last : '0) |
        ((cdma_128b_w_sel_subtractive && cdma_128b_wvalid) ? cdma_128b_w.last : '0);
    assign subtractive_axi_wuser = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.user : '0) |
        ((dma_128b_w_sel_subtractive && dma_128b_wvalid) ? dma_128b_w.user : '0) |
        ((atg_128b_w_sel_subtractive && atg_128b_wvalid) ? atg_128b_w.user : '0) |
        ((cdma_128b_w_sel_subtractive && cdma_128b_wvalid) ? cdma_128b_w.user : '0);
    assign subtractive_axi_wvalid = (cpu_128b_w_sel_subtractive && cpu_128b_wvalid) || (dma_128b_w_sel_subtractive && dma_128b_wvalid) || (atg_128b_w_sel_subtractive && atg_128b_wvalid) || (cdma_128b_w_sel_subtractive && cdma_128b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_bready = (cpu_128b_b_rgnt_subtractive ? cpu_128b_bready : '0) |
        (dma_128b_b_rgnt_subtractive ? dma_128b_bready : '0) |
        (atg_128b_b_rgnt_subtractive ? atg_128b_bready : '0) |
        (cdma_128b_b_rgnt_subtractive ? cdma_128b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign subtractive_axi_bridge_id_aw = (cpu_128b_aw_gnt_subtractive ? cpu_bridge_id_aw : '0) |
        (dma_128b_aw_gnt_subtractive ? dma_bridge_id_aw : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_bridge_id_aw : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_bridge_id_aw : '0);

    // AR request slots for subtractive: arbitration at the slave pins
    assign cpu_128b_ar_slot_subtractive_in_valid = cpu_128b_ar_to_subtractive && cpu_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_128b_ar_slot_subtractive_in_valid), .wr_ready(cpu_128b_ar_slot_subtractive_in_ready), .wr_data(cpu_128b_ar),
        .rd_valid(cpu_128b_ar_slot_subtractive_valid), .rd_ready(cpu_128b_ar_slot_subtractive_ready), .rd_data(cpu_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_128b_ar_slot_subtractive_in_valid = dma_128b_ar_to_subtractive && dma_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_dma_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_128b_ar_slot_subtractive_in_valid), .wr_ready(dma_128b_ar_slot_subtractive_in_ready), .wr_data(dma_128b_ar),
        .rd_valid(dma_128b_ar_slot_subtractive_valid), .rd_ready(dma_128b_ar_slot_subtractive_ready), .rd_data(dma_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign atg_128b_ar_slot_subtractive_in_valid = atg_128b_ar_to_subtractive && atg_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_atg_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(atg_128b_ar_slot_subtractive_in_valid), .wr_ready(atg_128b_ar_slot_subtractive_in_ready), .wr_data(atg_128b_ar),
        .rd_valid(atg_128b_ar_slot_subtractive_valid), .rd_ready(atg_128b_ar_slot_subtractive_ready), .rd_data(atg_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign cdma_128b_ar_slot_subtractive_in_valid = cdma_128b_ar_to_subtractive && cdma_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cdma_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cdma_128b_ar_slot_subtractive_in_valid), .wr_ready(cdma_128b_ar_slot_subtractive_in_ready), .wr_data(cdma_128b_ar),
        .rd_valid(cdma_128b_ar_slot_subtractive_valid), .rd_ready(cdma_128b_ar_slot_subtractive_ready), .rd_data(cdma_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for subtractive: round-robin, lock until handshake ----
    logic [3:0] subtractive_ar_arb_req;
    assign subtractive_ar_arb_req = {cdma_128b_ar_slot_subtractive_valid, atg_128b_ar_slot_subtractive_valid, dma_128b_ar_slot_subtractive_valid, cpu_128b_ar_slot_subtractive_valid};
    logic [1:0] subtractive_ar_arb_lock, subtractive_ar_arb_rr;
    logic subtractive_ar_arb_locked;
    wire [1:0] subtractive_ar_arb_pick = (subtractive_ar_arb_rr == 2'd0) ? (subtractive_ar_arb_req[0] ? 2'd0 : subtractive_ar_arb_req[1] ? 2'd1 : subtractive_ar_arb_req[2] ? 2'd2 : 2'd3) : 
        (subtractive_ar_arb_rr == 2'd1) ? (subtractive_ar_arb_req[1] ? 2'd1 : subtractive_ar_arb_req[2] ? 2'd2 : subtractive_ar_arb_req[3] ? 2'd3 : 2'd0) : 
        (subtractive_ar_arb_rr == 2'd2) ? (subtractive_ar_arb_req[2] ? 2'd2 : subtractive_ar_arb_req[3] ? 2'd3 : subtractive_ar_arb_req[0] ? 2'd0 : 2'd1) : 
        subtractive_ar_arb_req[3] ? 2'd3 : subtractive_ar_arb_req[0] ? 2'd0 : subtractive_ar_arb_req[1] ? 2'd1 : 2'd2;
    wire subtractive_ar_arb_gnt_valid = subtractive_ar_arb_locked || (|subtractive_ar_arb_req);
    wire [1:0] subtractive_ar_arb_gnt = subtractive_ar_arb_locked ? subtractive_ar_arb_lock : subtractive_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_ar_arb_lock   <= '0;
            subtractive_ar_arb_rr     <= '0;
            subtractive_ar_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_arvalid && subtractive_axi_arready) begin
                subtractive_ar_arb_locked <= 1'b0;
                subtractive_ar_arb_rr <= (subtractive_ar_arb_gnt == 2'd3) ? 2'd0 : subtractive_ar_arb_gnt + 1'b1;
            end else if (subtractive_axi_arvalid) begin
                subtractive_ar_arb_lock   <= subtractive_ar_arb_gnt;
                subtractive_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 2'd0) && subtractive_ar_arb_req[0];
    wire dma_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 2'd1) && subtractive_ar_arb_req[1];
    wire atg_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 2'd2) && subtractive_ar_arb_req[2];
    wire cdma_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 2'd3) && subtractive_ar_arb_req[3];
    assign cpu_128b_ar_slot_subtractive_ready = cpu_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign dma_128b_ar_slot_subtractive_ready = dma_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign atg_128b_ar_slot_subtractive_ready = atg_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign cdma_128b_ar_slot_subtractive_ready = cdma_128b_ar_gnt_subtractive && subtractive_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign subtractive_axi_arid = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.id : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.id : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.id : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.id : '0);
    assign subtractive_axi_araddr = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.addr : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.addr : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.addr : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.addr : '0);
    assign subtractive_axi_arlen = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.len : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.len : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.len : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.len : '0);
    assign subtractive_axi_arsize = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.size : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.size : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.size : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.size : '0);
    assign subtractive_axi_arburst = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.burst : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.burst : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.burst : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.burst : '0);
    assign subtractive_axi_arlock = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.lock : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.lock : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.lock : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.lock : '0);
    assign subtractive_axi_arcache = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.cache : '0) |
        (dma_128b_ar_gnt_subtractive ? dma_128b_ar_slot_subtractive.cache : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.cache : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.cache : '0);
    assign subtractive_axi_arprot = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.prot : '0) |
